beforeExample:
class HtmlFormatter {
    public void format(StringBuffer buffer) {
        buffer.append("<html><body><p>Some text</p></font></body></html>");
        buffer.append("</font></body></html>");
    }
}

afterExample:
class HtmlFormatter {
    public void format(StringBuffer buffer) {
        buffer.append("<html><body><p>Some text</p></font></body></html>");
        buffer.append("</body></html>");
    }
}

